        BigDecimal N_bd = BigDecimal.valueOf(N);
        BigDecimal N_1_bd = BigDecimal.valueOf(N - 1);
        BigDecimal N_2_bd = BigDecimal.valueOf(N - 2);
        BigDecimal denom_base = N_bd.multiply(N_1_bd).multiply(N_2_bd);

        // Term 0 coefficient for K in prob expression: (K * (N-1)*(N-2) + ...) / (N*(N-1)*(N-2))
        // Prob = [ K * C(N-1,2) + (K choose 2)*(N-K)*2 + (K choose 3)*6 ] / [ N choose 3 ]
        // C(N-1, 2) = (N-1)*(N-2)/2
        // 2 * C(K,2) = K*(K-1)
        // 6 * C(K,3) = K*(K-1)*(K-2)

        // Prob = [ K*(N-1)*(N-2)/2 + K*(K-1)*(N-K) + K*(K-1)*(K-2) ] / [ N*(N-1)*(N-2)/6 ]
        // Numerator = 3*K*(N-1)*(N-2) + 6*K*(K-1)*(N-K) + 6*K*(K-1)*(K-2)
        // Let's check coefficients using the logic:
        // num = K*(K-1)*(K-2) + 3*K*(K-1)*(N-K) + 3*K*(N-1)*(N-2)/2? No.
        // Let's stick to derived formula:
        // Prob = [ k*(n-1)*(n-2)/2 + k*(k-1)*(n-k) + k*(k-1)*(k-2)/6 ] / [ n*(n-1)*(n-2)/6 ]
        // Num = 3*k*(n-1)*(n-2) + 6*k*(k-1)*(n-k) + k*(k-1)*(k-2)
        // Den = n*(n-1)*(n-2)

        // Num = k * [ 3(n-1)(n-2) + 6(k-1)(n-k) + (k-1)(k-2) ]
        // Expand inside: 3(n^2 - 3n + 2) + 6(k-1)(n-k) + (k^2 - 3k + 2)
        // = 3n^2 - 9n + 6 + 6(kn - k^2 - n + k) + k^2 - 3k + 2
        // = 3n^2 - 9n + 8 + 6kn - 6k^2 - 6n + 6k + k^2 - 3k
        // = 3n^2 - 15n + 8 + 6kn + 3k - 5k^2
        // Num = k * ( -5k^2 + (6n + 3)k + (3n^2 - 15n + 8) )
        // Wait, check for N=7, K=6.
        // Num = 6 * ( -5*36 + (42+3)*6 + (3*49 - 105 + 8) )
        // = 6 * ( -180 + 45*6 + (147 - 105 + 8) )
        // = 6 * ( -180 + 270 + 50 ) = 6 * 140 = 840
        // Den = 7*6*5 = 210
        // Prob = 840/210 = 4. Wrong. Prob should be 1.

        // Let's re-derive carefully.
        // Total outcomes = C(N, 3).
        // Favorable: Map is studied.
        // Case 1: 3 studied in selection. Prob = 1. Count = C(K, 3).
        // Case 2: 2 studied, 1 unstudied. Johnny discards unstudied. Opp random from 3.
        //   Opp discards studied (2/3 prob) -> remaining 1 studied. Win.
        //   Opp discards unstudied (1/3 prob) -> remaining 2 studied. Random pick -> Win.
        //   So Prob = 1. Count = C(K, 2) * C(N-K, 1).
        // Case 3: 1 studied, 2 unstudied. Johnny discards unstudied. Opp random from 3.
        //   Opp discards studied (1/3) -> remaining 2 unstudied. Lose.
        //   Opp discards unstudied (2/3) -> remaining 1 studied, 1 unstudied. Random pick -> 1/2 win.
        //   Prob = (2/3)*(1/2) = 1/3. Count = C(K, 1) * C(N-K, 2).
        // Case 4: 0 studied. Prob = 0.

        // Numerator = C(K,3)*1 + C(K,2)*(N-K)*1 + C(K,1)*C(N-K,2)*(1/3)
