        // Num = K(K-1)(K-2)/6 + K(K-1)/2 * (N-K) + K * (N-K)(N-K-1)/2 * 1/3
        // Num = K/6 * [ (K-1)(K-2) + 3(K-1)(N-K) + (N-K)(N-K-1) ]
        // Let U = N-K.
