        // Possible selections: {S,S,U} (4 ways? C(2,2)*C(2,1)=2. {S,U,U} C(2,1)*C(2,2)=2.)
        // {S,S,U}: Johnny discards U. Opp random 3. Discard S (2/3) -> S remains. Discard U (1/3) -> S,S remain. Win prob 1.
        // {S,U,U}: Johnny discards U. Opp random 3. Discard S (1/3) -> U,U remain Lose. Discard U (2/3) -> S,U remain -> 1/2 win.
        // Total Prob = (2/4)*1 + (2/4)*(1/3) = 0.5 + 1/6 = 2/3.
        // Formula: K=2, N=4.
        // Inside = -4 + 5*2 + 16 - 16 + 2 = -4 + 10 + 2 = 8.
        // Num = 2*8 = 16.
        // Den = 4*3*2 = 24.
        // Prob = 16/24 = 2/3. Correct.

        BigDecimal den = N_bd.multiply(N_1_bd).multiply(N_2_bd);

        for (int k = 1; k <= N - 1; k++) {
            BigDecimal K_bd = BigDecimal.valueOf(k);
            BigDecimal K2 = K_bd.multiply(K_bd);
            BigDecimal K3 = K2.multiply(K_bd);

            // Inside = -K^2 + (N+1)K + N^2 - 4N + 2
            BigDecimal N_plus_1 = N_bd.add(BigDecimal.ONE);
            BigDecimal N2 = N_bd.multiply(N_bd);
            BigDecimal fourN = N_bd.multiply(BigDecimal.valueOf(4));

            BigDecimal inside = K2.negate()
                              .add(K_bd.multiply(N_plus_1))
                              .add(N2)
                              .subtract(fourN)
                              .add(BigDecimal.valueOf(2));

            BigDecimal num = K_bd.multiply(inside);
            BigDecimal prob = num.divide(den, 10, RoundingMode.HALF_UP); // Enough precision

            if (prob.compareTo(P) >= 0) {
                System.out.println(k);
                return;
            }
        }
        System.out.println(N - 1);
    }
}
